INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-04' FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Real-time DIAN clearance via CUFE, universal since November 2020 -- one of Latin America''s oldest and most complete CTC mandates', 'This deep-dive page reflects publicly available guidance and reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Colombia''s e-invoicing rules change through frequent DIAN resolutions; confirm current requirements directly with DIAN or a local tax advisor before relying on this page for compliance decisions.', 'Colombia recognized electronic invoices legally as early as 1995 and built its modern clearance system from Decree 2242/2015 onward, starting with voluntary pilots across 18 economic sectors. DIAN Resolution 000010/2018 ordered the first mandatory wave -- large taxpayers -- onto real-time clearance from 1 September 2018. Resolution 000042/2020 then staged the remaining taxpayer groups through 2020, with the final wave (Groups 6-8) landing on 1 November 2020 and making the mandate effectively universal for every VAT- and national-consumption-tax-responsible business. Since going universal, DIAN has broadened the system to new document types -- Resolution 000165/2023 converted paper "documentos equivalentes" (POS receipts, utility bills, transport and airline tickets) into electronic, DIAN-validated documents, a rollout completed by 1 November 2024 -- and refined it procedurally, most recently with Resolution 000202/2025''s streamlined buyer-data capture and a 2026 mechanism (Resolution 000011/2026) letting businesses regularize previously un-invoiced operations.', 'Every electronic sales invoice (Factura Electrónica de Venta) is built as UBL 2.1 XML with DIAN-specific extensions, carries an X.509 digital signature, and is stamped with a CUFE (Código Único de Factura Electrónica) -- a 96-character SHA-384 hash of the invoice''s key data -- plus a QR code on any PDF rendition for public verification via DIAN''s portal.', 'Coverage is close to universal: every VAT-responsible taxpayer (common regime), National Consumption Tax payers, Simple Tax Regime (SIMPLE) taxpayers, and large taxpayers are all in scope for B2B, B2C, and B2G sales alike. Only non-VAT filers with income below 3,500 UVT (roughly COP 183.3 million in 2026) and a small list of other exempt categories sit outside the mandate, and even many of those may adopt it voluntarily.', 'Because the mandate is already universal, the real ongoing work for a business already invoicing in Colombia is keeping pace with DIAN''s procedural refinements and its expansion into adjacent document types -- equivalent documents, electronic payroll, and now RADIAN -- rather than working out whether e-invoicing applies at all.', 'Colombia backs its mandate with a real, tiered enforcement structure: formality fines under Article 652 of the Estatuto Tributario, escalating to a temporary closure of the business premises under Article 657 for failing to invoice at all, plus the practical pressure of buyers losing their VAT credit and cost deductions on non-compliant invoices.', 'Colombia''s DIAN operates a real-time pre-validation clearance system: every Factura Electrónica de Venta must be transmitted to DIAN and receive a CUFE before it reaches the buyer, making the invoice legally valid only once DIAN has approved it. The mandate began with large taxpayers under Resolution 000010/2018 (1 September 2018) and became effectively universal for VAT- and consumption-tax-responsible businesses when Resolution 000042/2020''s final taxpayer wave landed on 1 November 2020. DIAN has since broadened the system to cover "documentos equivalentes electrónicos" -- POS receipts, utility bills, and transport/airline tickets -- under Resolution 000165/2023, a rollout completed by 1 November 2024, and refined buyer-data and rural-transmission rules under Resolution 000202/2025. A 2026 mechanism, Resolution 000011/2026, now lets businesses voluntarily regularize previously un-invoiced operations using a special "20-REG" code. Non-compliance carries real consequences: a 1%-of-value formality fine capped at 950 UVT (Article 652), and temporary establishment closure of 3 to 10 days for failing to invoice altogether (Article 657).', '🇨🇴' FROM countries WHERE name_en = 'Colombia';
