INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '3-10 days', 'Closure penalty range for non-issuance (Art. 657)');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Format", "UBL 2.1 XML with DIAN-specific extensions"], ["Digital signature", "X.509 certificate from an accredited Colombian certification authority"], ["CUFE", "96-character SHA-384 hash of key invoice data, generated on validation"], ["QR code", "Mandatory on PDF renditions, enabling public verification via DIAN''s portal"]]', 'Colombia''s UBL-based format is closer to the European EN 16931 world than Argentina''s domestic XML schema is -- a real practical advantage for multinational businesses running the same invoicing stack across both regions.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer ID", "NIT (Número de Identificación Tributaria)"], ["Registration", "Enrollment with DIAN plus an accredited technology provider, or DIAN''s own free invoicing portal for qualifying small businesses"], ["Governing body", "DIAN -- Dirección de Impuestos y Aduanas Nacionales"], ["Issuance channels", "Certified technology-provider software, DIAN''s free portal, or a direct system-to-system integration"]]', 'The free DIAN portal keeps compliance genuinely reachable for the smallest taxpayers, not just those who can afford commercial invoicing software.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Core fields", "Issuer/buyer NIT, invoice type, date, line items, VAT/INC breakdown, CUFE"], ["Since Resolution 000202/2025", "POS invoices may capture only name, ID type/number, and email for buyers not already in DIAN''s registry"], ["RADIAN", "Invoices can be registered as negotiable instruments, enabling factoring through recorded endorsements"], ["Retention", "5+ years, by both issuer and buyer"]]', 'RADIAN is a genuinely distinctive feature this tracker hasn''t seen elsewhere: turning a validated e-invoice into a tradeable financial instrument, not just a tax record.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Invoicing model", "Real-time clearance -- DIAN validates and issues a CUFE, typically in seconds, before the invoice reaches the buyer"], ["Coverage", "B2B, B2C, and B2G -- effectively universal since 1 November 2020"], ["Contingency", "A documented offline procedure with retrospective transmission once systems are restored"], ["Without a valid CUFE", "The invoice has no fiscal validity, and the buyer cannot claim related costs or VAT credits"]]', 'Like Argentina, this is a genuine pre-delivery clearance model, not a post-audit reporting one -- the invoice is not legally complete until DIAN has already validated it.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s actually mandatory today', '[["Large taxpayers", "Mandatory since 1 September 2018 (Resolution 000010/2018)"], ["All VAT/INC-responsible businesses", "Mandatory since 1 November 2020 (Resolution 000042/2020)"], ["Equivalent documents (POS, utilities, transport/air tickets)", "Fully electronic since 1 November 2024 (Resolution 000165/2023 + 000008/2024)"], ["Exempt", "Non-VAT filers with income below 3,500 UVT (~COP 183.3 million in 2026), plus a short list of other categories"]]', 'The exemption threshold is one of the few genuine carve-outs left in this mandate -- most Colombian businesses above a modest size have no way to avoid electronic invoicing.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Actively evolving, not a settled system', '[["2023-2024", "Equivalent electronic documents phased in (Resolution 000165/2023, extended by 000008/2024)"], ["31 Mar 2025", "Streamlined buyer data and a 48-hour rural transmission window (Resolution 000202/2025)"], ["23 Sep 2025", "DIAN consolidated e-invoicing rules (plus 60+ other tax regulations) into one unified resolution, 000227/2025"], ["23 Apr 2026", "A voluntary regularization mechanism for previously un-invoiced operations (Resolution 000011/2026)"]]', 'Colombia''s mandate reached universal coverage back in 2020, but DIAN keeps issuing genuine procedural and scope refinements every year since -- treat it as an actively maintained system, not a box checked once in 2020.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Closure, not just a fine, for failing to invoice', NULL, NULL, 'Under Article 657 of the Estatuto Tributario, DIAN may order a temporary closure of the business premises -- typically 3 to 10 days -- for failing to issue required electronic invoices, or the business may instead pay a sum equal to 5% of the prior month''s gross revenue to avoid closure. This is a materially harder consequence than a flat fine.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 No CUFE, no deduction', NULL, NULL, 'An invoice lacking proper DIAN validation has no fiscal support value: the buyer holding it cannot claim the related cost deduction or VAT credit, and DIAN actively cross-references invoicing data against income-tax filings and electronic payroll records to find gaps. The market pressure this creates is often a stronger compliance driver than the fines themselves.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌎 A second chance for past gaps, not an amnesty going forward', NULL, NULL, 'Resolution 000011/2026 lets businesses voluntarily regularize previously un-invoiced or improperly invoiced operations by transmitting a special "type 3" document tagged "20-REG" -- reducing fiscal risk for genuine past gaps without touching DIAN''s ordinary enforcement powers for anything going forward.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice issued without full legal requirements (formality error)', '1% of the transaction value', 'Capped at 950 UVT (≈ COP 49.7 million in 2026)');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice not issued at all', 'Temporary closure of the business premises (3-10 days), or 5% of the prior month''s gross revenue in lieu', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your invoicing software transmits every invoice to DIAN for real-time CUFE validation before delivery', 'An invoice lacking a valid CUFE has no fiscal support value for either side of the transaction -- the single most important check for any business already invoicing in Colombia.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you issue POS receipts, utility bills, or transport/airline tickets, confirm you''re on the fully electronic equivalent-document format', 'This phase-in completed 1 November 2024 under Resolution 000165/2023 as extended by Resolution 000008/2024 -- there''s no remaining paper option for standard categories.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Adopt Resolution 000202/2025''s streamlined buyer-data flow, and the 48-hour rural transmission window if it applies to you', 'Point-of-sale systems still capturing more buyer data than required, or utility providers in low-connectivity areas not yet using the contingency window, are behind current DIAN guidance.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Keep electronic payroll (nómina electrónica) filings current alongside your invoicing', 'DIAN cross-references labor payments reported in electronic payroll against declared costs, deductions, and monthly withholdings -- a mismatch here draws the same scrutiny as an invoicing gap.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Colombia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you have historical invoicing gaps, review Resolution 000011/2026''s "20-REG" regularization mechanism before an audit surfaces them', 'It lets you voluntarily transmit previously un-invoiced operations using a special code, reducing fiscal risk -- but it doesn''t limit DIAN''s ordinary enforcement powers going forward.');
